def bbox(cells):
    """(top,bottom,left,right) of a list of (row,col) cells."""
    rows=[i for i,_ in cells]; cols=[j for _,j in cells]
    return min(rows),max(rows),min(cols),max(cols)

def top_row(cells):
    """The cells of the topmost row of an object, sorted by column."""
    t=min(i for i,_ in cells)
    return sorted(j for i,j in cells if i==t)

def align_tops(grid, anchor_color=None):
